class ModInt {
    constructor(n) {
        this.v = n % MOD;
        if (this.v < 0) this.v += MOD;
    }

    static zero() { return new ModInt(0); }
    static one() { return new ModInt(1); }

    add(rhs) {
        let d = this.v + rhs.v;
        if (d >= MOD) d -= MOD;
        return new ModInt(d);
    }

    sub(rhs) {
        let d = this.v + MOD - rhs.v;
        if (d >= MOD) d -= MOD;
        return new ModInt(d);
    }

    mul(rhs) {
        return new ModInt((this.v * rhs.v) % MOD);
    }

    neg() {
        return new ModInt(this.v === 0 ? 0 : MOD - this.v);
    }

    pow(n) {
        let t = ModInt.one();
        let s = new ModInt(this.v);
        while (n > 0) {
            if (n & 1) t = t.mul(s);
            s = s.mul(s);
            n >>= 1;
        }
        return t;
    }

    inv() {
        return this.pow(MOD - 2);
    }

    static comb(n, k) {
        if (k > n) return ModInt.zero();
        k = Math.min(k, n - k);
        let nu = ModInt.one();
        let de = ModInt.one();
        for (let i = 0; i < k; i++) {
            nu = nu.mul(new ModInt(n - i));
            de = de.mul(new ModInt(i + 1));
        }
        return nu.mul(de.inv());
    }
}

class Precalc {
    constructor(n) {
        this.inv = Array(n + 1);
        this.fact = Array(n + 1);
        this.ifact = Array(n + 1);
        for (let i = 0; i <= n; i++) {
            this.inv[i] = ModInt.one();
            this.fact[i] = ModInt.one();
            this.ifact[i] = ModInt.one();
        }
        for (let i = 2; i <= n; i++) {
            this.inv[i] = this.inv[MOD % i].neg().mul(new ModInt(Math.floor(MOD / i)));
